const project = $input.first().json;
const webhookBody = $('Project Intake Webhook').first().json.body || {};
const executionDbId = webhookBody.execution_id || null;

const services = Array.isArray(project.services) ? project.services : [];
const summary = `Automated intake validation and delivery plan generated by n8n for ${project.company_name} (${project.intake_id}).`;
const content = `## Project Intake Automation Report\n\n- **Company:** ${project.company_name}\n- **Intake ID:** ${project.intake_id}\n- **Industry:** ${project.industry || 'N/A'}\n- **Goal:** ${project.goal || 'N/A'}\n- **Budget:** $${Number(project.monthly_budget || 0).toFixed(2)}\n- **Services:** ${services.join(', ') || 'None'}\n\n### Automated Action Plan\n1. Intake validated in PostgreSQL.\n2. Service tracks initialized for ${services.length} selected streams.\n3. Deliverable logged to outputs table.`;

return [{
  json: {
    project_id: project.id,
    intake_id: project.intake_id,
    execution_db_id: executionDbId,
    n8n_execution_id: $execution.id,
    title: `Automated Strategy & Intake Validation — ${project.company_name}`,
    output_type: 'strategy',
    summary,
    content,
    data_json: JSON.stringify({
      validated: true,
      services_count: services.length,
      priority: project.priority,
      processed_by: 'n8n'
    })
  }
}];

