INSERT INTO outputs (project_id, execution_id, title, output_type, summary, content, data, status, created_at) VALUES ({{ $json.project_id }}, {{ $json.execution_db_id || 'NULL' }}, '{{ $json.title.replace(/'/g, "''") }}', '{{ $json.output_type }}', '{{ $json.summary.replace(/'/g, "''") }}', '{{ $json.content.replace(/'/g, "''") }}', '{{ $json.data_json }}'::jsonb, 'generated', NOW());
UPDATE projects SET status = 'Completed', updated_at = NOW() WHERE id = {{ $json.project_id }};
UPDATE executions SET status = 'success', n8n_execution_id = '{{ $json.n8n_execution_id }}', finished_at = NOW() WHERE id = {{ $json.execution_db_id || 0 }};
